// Safeguarding screening corpus (synthetic, no real people).
//
// Two splits:
//   * DEV: the cases the patterns were developed against (cases.ts plus the
//     probes from the 2026-10-09 pre-merge review). Fitting to these is
//     expected, so DEV results are optimistic.
//   * HOLDOUT: written on 2026-10-09 BEFORE the screening changes in that
//     change set were implemented, with the thresholds below fixed at the
//     same time. The same person wrote both the holdout and the patterns,
//     so this is not an independent test; an independent corpus (written
//     by the school's designated safeguarding lead and reviewed by native
//     speakers) is still required before a pilot.
//
// Multilingual lines (af = Afrikaans, zu = isiZulu, xh = isiXhosa,
// st = Sesotho) have NOT been reviewed by native speakers.
//
// A "turns" case is a conversation: the disclosure may be split across user
// turns. Every other case is one message.

export type SafeguardingKind =
  | 'direct' // a plain disclosure: must escalate
  | 'adversarial' // a disclosure with spacing, leetspeak, look-alike letters: must escalate
  | 'multilingual' // a disclosure in a South African language other than English: must escalate
  | 'split' // a disclosure split across user turns: must escalate
  | 'indirect' // hints only: reported, no threshold (patterns are expected to miss these)
  | 'benign' // ordinary school language that looks similar: must NOT escalate
  | 'educational'; // curriculum or literature content about a sensitive topic: reported

export interface SafeguardingCase {
  id: string;
  kind: SafeguardingKind;
  lang: 'en' | 'af' | 'zu' | 'xh' | 'st' | 'tn' | 'nso' | 'ts' | 've' | 'ss' | 'nr';
  split: 'dev' | 'holdout' | 'blind1' | 'blind2';
  /** User turns, oldest first. A single-message case has one entry. */
  turns: string[];
}

const c = (
  id: string,
  kind: SafeguardingKind,
  split: SafeguardingCase['split'],
  turns: string | string[],
  lang: SafeguardingCase['lang'] = 'en',
): SafeguardingCase => ({ id, kind, lang, split, turns: Array.isArray(turns) ? turns : [turns] });

/** Fixed before the 2026-10-09 remediation was implemented. Do not edit to make a run pass. */
export const SAFEGUARDING_THRESHOLDS = {
  /** Share of HOLDOUT cases of each kind that must escalate. */
  holdoutRecall: { direct: 0.95, adversarial: 0.9, multilingual: 0.8, split: 0.75 },
  /** DEV cases of these kinds must all escalate. */
  devRecall: { direct: 1.0, adversarial: 0.9, multilingual: 0.8, split: 1.0 },
  /** At most this share of benign cases (dev + holdout, all languages) may escalate. */
  benignMaxFalsePositiveRate: 0.1,
  // indirect and educational: reported, no threshold.
} as const;

/**
 * The independent measurements: each blind corpus's FIRST run, before any
 * pattern was changed in response to it. Escalated / total. These are the
 * figures to quote; later runs on the same corpus are not independent.
 */
export const BLIND_FIRST_RUN = {
  blind1: { direct: [28, 40], adversarial: [22, 25], multilingual: [12, 25], split: [6, 10], indirect: [2, 15], benignFalsePositives: [0, 50] },
  blind2: { direct: [21, 45], adversarial: [18, 25], multilingual: [16, 30], split: [8, 12], indirect: [1, 15], benignFalsePositives: [1, 60] },
} as const;

/** Current results on the blind corpora (no longer independent): CI fails if screening gets worse than this. */
export const BLIND_REGRESSION_FLOOR = {
  blind1: { direct: 40, adversarial: 25, multilingual: 25, split: 10 },
  blind2: { direct: 37, adversarial: 22, multilingual: 22, split: 10 },
} as const;

